import {Ecosystem} from './simulation.js';
let sim,speed=1,paused=false,last=performance.now(),accumulator=0,publishClock=0,timer;
const publish=(type='state',cpuMs=0)=>self.postMessage({type,state:sim.snapshot(),cpuMs,backlog:accumulator});
const attach=()=>sim.onEvent=event=>self.postMessage({type:'event',event});
self.onmessage=({data:m})=>{try{if(m.type==='init'){sim=new Ecosystem(m.saved);attach();last=performance.now();publish('ready');if(timer)clearInterval(timer);timer=setInterval(tick,50);return;}if(!sim)return;if(m.type==='control'){speed=m.speed??speed;paused=m.paused??paused;accumulator=0;last=performance.now();}if(m.type==='climate')sim.setClimate(m.key,m.value);if(m.type==='intervene'){self.postMessage({type:'notice',message:sim.intervene(m.tool,m.x,m.z)});publish();}if(m.type==='name'){const c=sim.byId.get(m.id)||sim.archive.find(c=>c.id===m.id);if(c){c.named=true;if(m.name)c.name=m.name.trim().slice(0,28);for(const o of [...sim.creatures,...sim.archive]){if(o.mother===c.id)o.motherName=c.name;if(o.father===c.id)o.fatherName=c.name;if(o.pregnancy?.father===c.id)o.pregnancy.fatherName=c.name;}publish();}}if(m.type==='reset'){sim=new Ecosystem();attach();accumulator=0;paused=false;last=performance.now();publish('reset');}if(m.type==='snapshot')publish();}catch(e){self.postMessage({type:'error',message:e.message});}};
function tick(){if(!sim)return;try{const now=performance.now(),elapsed=Math.min(2,(now-last)/1000);last=now;publishClock+=elapsed;if(!paused)accumulator=Math.min(4,accumulator+elapsed*speed);const start=performance.now();let steps=0;while(accumulator>=.1&&steps<40){sim.step(.1);accumulator-=.1;steps++;if(performance.now()-start>24)break;}if(publishClock>=.2){publishClock=0;publish('state',performance.now()-start);}}catch(e){paused=true;self.postMessage({type:'error',message:e.message});}}
